    public async Task Claim_bound_proposal_endpoints_preserve_inbox_privacy_and_return_conflict_for_stale_race()
    {
        await using var factory=new HambaftApiFactory(fixture.ConnectionString);using var client=factory.CreateClient();var packages=await Body(await client.GetAsync("/api/story-packages"));var package=packages.EnumerateArray().Single(x=>x.GetProperty("id").GetString()=="sample-cargo-delay"&&x.GetProperty("version").GetString()=="1.1.0");var hash=package.GetProperty("contentHash").GetString()!;
