        var supplierEntity=(await Body(await client.PostAsJsonAsync($"/api/sessions/{session}/entities",new{definitionId="supplier",displayName="Supplier",controllerType="HumanTeam",behaviorProfileId=(string?)null,expectedVersion=3}))).GetProperty("resourceId").GetGuid();var carrierEntity=(await Body(await client.PostAsJsonAsync($"/api/sessions/{session}/entities",new{definitionId="carrier",displayName="Carrier",controllerType="HumanTeam",behaviorProfileId=(string?)null,expectedVersion=4}))).GetProperty("resourceId").GetGuid();await client.PostAsJsonAsync($"/api/sessions/{session}/entities",new{definitionId="credit-provider",displayName="Credit",controllerType="AuthoredBehavior",behaviorProfileId="cooperative-credit",expectedVersion=5});(await client.PostAsJsonAsync($"/api/sessions/{session}/assignments",new{entityId=supplierEntity,teamId=supplier,expectedVersion=6})).EnsureSuccessStatusCode();(await client.PostAsJsonAsync($"/api/sessions/{session}/assignments",new{entityId=carrierEntity,teamId=carrier,expectedVersion=7})).EnsureSuccessStatusCode();(await client.PostAsJsonAsync($"/api/sessions/{session}/start",new{expectedVersion=8})).EnsureSuccessStatusCode();
        var supplierToken=await Pair(client,session,supplier,supplierCode);var carrierToken=await Pair(client,session,carrier,carrierCode);var adminToken=factory.Services.GetRequiredService<JwtTokenIssuer>().IssueAdmin(session).AccessToken;var initialized=await Body(await Send(client,HttpMethod.Post,$"/api/sessions/{session}/narrative/initialize",adminToken,new{expectedStateVersion=9,commandId=Guid.NewGuid()}));var version=initialized.GetProperty("stateVersion").GetInt64();
        await using var supplierHub=Hub(factory,supplierToken);await using var carrierHub=Hub(factory,carrierToken);await using var displayHub=Hub(factory,factory.Services.GetRequiredService<JwtTokenIssuer>().IssuePublicDisplay(session).AccessToken);var supplierReceived=new ConcurrentQueue<InteractionNotification>();var carrierReceived=new ConcurrentQueue<InteractionNotification>();var supplierCountered=new ConcurrentQueue<InteractionNotification>();var carrierCountered=new ConcurrentQueue<InteractionNotification>();var supplierAccepted=new ConcurrentQueue<InteractionNotification>();var carrierAccepted=new ConcurrentQueue<InteractionNotification>();var displayActivated=new ConcurrentQueue<InteractionNotification>();var supplierExpired=new ConcurrentQueue<InteractionNotification>();var carrierExpired=new ConcurrentQueue<InteractionNotification>();var supplierExecuted=new ConcurrentQueue<InteractionNotification>();var carrierExecuted=new ConcurrentQueue<InteractionNotification>();var displayExecuted=new ConcurrentQueue<InteractionNotification>();var supplierRejected=new ConcurrentQueue<InteractionNotification>();var carrierRejected=new ConcurrentQueue<InteractionNotification>();var supplierCancelled=new ConcurrentQueue<InteractionNotification>();var carrierCancelled=new ConcurrentQueue<InteractionNotification>();var supplierConsequences=new ConcurrentQueue<NarrativeNotification>();var carrierConsequences=new ConcurrentQueue<NarrativeNotification>();var displayConsequences=new ConcurrentQueue<NarrativeNotification>();var displayBehavior=new ConcurrentQueue<NarrativeNotification>();supplierHub.On<InteractionNotification>("ProposalReceived",supplierReceived.Enqueue);carrierHub.On<InteractionNotification>("ProposalReceived",carrierReceived.Enqueue);supplierHub.On<InteractionNotification>("ProposalCountered",supplierCountered.Enqueue);carrierHub.On<InteractionNotification>("ProposalCountered",carrierCountered.Enqueue);supplierHub.On<InteractionNotification>("ProposalAccepted",supplierAccepted.Enqueue);carrierHub.On<InteractionNotification>("ProposalAccepted",carrierAccepted.Enqueue);displayHub.On<InteractionNotification>("AgreementActivated",displayActivated.Enqueue);supplierHub.On<InteractionNotification>("ProposalExpired",supplierExpired.Enqueue);carrierHub.On<InteractionNotification>("ProposalExpired",carrierExpired.Enqueue);supplierHub.On<InteractionNotification>("AgreementExecuted",supplierExecuted.Enqueue);carrierHub.On<InteractionNotification>("AgreementExecuted",carrierExecuted.Enqueue);displayHub.On<InteractionNotification>("AgreementExecuted",displayExecuted.Enqueue);supplierHub.On<InteractionNotification>("ProposalRejected",supplierRejected.Enqueue);carrierHub.On<InteractionNotification>("ProposalRejected",carrierRejected.Enqueue);supplierHub.On<InteractionNotification>("ProposalCancelled",supplierCancelled.Enqueue);carrierHub.On<InteractionNotification>("ProposalCancelled",carrierCancelled.Enqueue);supplierHub.On<NarrativeNotification>("ConsequenceChanged",supplierConsequences.Enqueue);carrierHub.On<NarrativeNotification>("ConsequenceChanged",carrierConsequences.Enqueue);displayHub.On<NarrativeNotification>("ConsequenceChanged",displayConsequences.Enqueue);displayHub.On<NarrativeNotification>("AuthoredBehaviorResolved",displayBehavior.Enqueue);await supplierHub.StartAsync();await carrierHub.StartAsync();await displayHub.StartAsync();
        var supplierStateChanged=new ConcurrentQueue<StateChangedNotification>();supplierHub.On<StateChangedNotification>("StateChanged",supplierStateChanged.Enqueue);
        var sentResponse=await Send(client,HttpMethod.Post,"/api/proposals",supplierToken,new{interactionTypeId="emergency-capacity-support",receiverTeamId=carrier,termsPayload=new{capacityUnits=8,supportDurationCheckpoints=1,publicDisclosure=true},validityType=(string?)null,validForCheckpointCount=(int?)null,validUntilCheckpointId=(string?)null,expectedStateVersion=version,commandId=Guid.NewGuid()});sentResponse.StatusCode.Should().Be(HttpStatusCode.Created);var sent=await Body(sentResponse);var proposal=sent.GetProperty("resourceId").GetGuid();version=sent.GetProperty("stateVersion").GetInt64();await WaitFor(carrierReceived,1);supplierReceived.Should().BeEmpty();carrierReceived.Single().ProposalId.Should().Be(proposal);var carrierInbox=await Body(await Get(client,"/api/proposals/inbox",carrierToken));carrierInbox.GetProperty("incoming").GetArrayLength().Should().Be(1);var supplierInbox=await Body(await Get(client,"/api/proposals/inbox",supplierToken));supplierInbox.GetProperty("incoming").GetArrayLength().Should().Be(0);var supplierOutbox=await Body(await Get(client,"/api/proposals/outbox",supplierToken));supplierOutbox.GetProperty("outgoing").GetArrayLength().Should().Be(1);
        var countered=await Body(await Send(client,HttpMethod.Post,$"/api/proposals/{proposal}/counter",carrierToken,new{expectedRevisionNumber=1,termsPayload=new{capacityUnits=12,supportDurationCheckpoints=2,publicDisclosure=false},expectedStateVersion=version,commandId=Guid.NewGuid()}));version=countered.GetProperty("stateVersion").GetInt64();await WaitFor(supplierCountered,1);carrierCountered.Should().BeEmpty();(await Body(await Get(client,"/api/proposals/inbox",supplierToken))).GetProperty("incoming")[0].GetProperty("currentRevisionNumber").GetInt32().Should().Be(2);
        var accepted=await Body(await Send(client,HttpMethod.Post,$"/api/proposals/{proposal}/accept",supplierToken,new{expectedRevisionNumber=2,expectedStateVersion=version,commandId=Guid.NewGuid()}));var acceptedVersion=accepted.GetProperty("stateVersion").GetInt64();await WaitFor(supplierAccepted,1);await WaitFor(carrierAccepted,1);await WaitFor(displayActivated,1);var agreements=await Body(await Get(client,"/api/agreements",carrierToken));agreements.GetArrayLength().Should().Be(1);agreements[0].GetProperty("status").GetInt32().Should().Be(0);
        var stale=await Send(client,HttpMethod.Post,$"/api/proposals/{proposal}/reject",supplierToken,new{expectedRevisionNumber=2,expectedStateVersion=version,commandId=Guid.NewGuid()});stale.StatusCode.Should().Be(HttpStatusCode.Conflict);using(var problem=JsonDocument.Parse(await stale.Content.ReadAsStringAsync()))problem.RootElement.GetProperty("status").GetInt32().Should().Be(409);acceptedVersion.Should().BeGreaterThan(version);
        var supplierExperience=await Body(await Get(client,"/api/story/experience",supplierToken));var carrierExperience=await Body(await Get(client,"/api/story/experience",carrierToken));var supplierAssignment=supplierExperience.GetProperty("privateStorylets")[0].GetProperty("assignmentId").GetGuid();var carrierAssignment=carrierExperience.GetProperty("privateStorylets")[0].GetProperty("assignmentId").GetGuid();var choice1=await Body(await Send(client,HttpMethod.Post,"/api/story/choices",supplierToken,new{assignmentId=supplierAssignment,choiceId="promise-original-deadline",expectedStateVersion=acceptedVersion,commandId=Guid.NewGuid()}));var choice2=await Body(await Send(client,HttpMethod.Post,"/api/story/choices",carrierToken,new{assignmentId=carrierAssignment,choiceId="reserve-emergency-capacity",expectedStateVersion=choice1.GetProperty("stateVersion").GetInt64(),commandId=Guid.NewGuid()}));var unanswered=await Body(await Send(client,HttpMethod.Post,"/api/proposals",supplierToken,new{interactionTypeId="emergency-capacity-support",receiverTeamId=carrier,termsPayload=new{capacityUnits=3,supportDurationCheckpoints=1,publicDisclosure=false},validityType=(string?)null,validForCheckpointCount=(int?)null,validUntilCheckpointId=(string?)null,expectedStateVersion=choice2.GetProperty("stateVersion").GetInt64(),commandId=Guid.NewGuid()}));var firstResolve=await Body(await Send(client,HttpMethod.Post,$"/api/sessions/{session}/narrative/resolve",adminToken,new{expectedStateVersion=unanswered.GetProperty("stateVersion").GetInt64(),commandId=Guid.NewGuid()}));await WaitFor(supplierExpired,1);await WaitFor(carrierExpired,1);await WaitFor(supplierExecuted,1);await WaitFor(carrierExecuted,1);await WaitFor(displayExecuted,1);await WaitFor(displayBehavior,1);await WaitFor(displayConsequences,1);supplierConsequences.Should().NotBeEmpty();carrierConsequences.Should().NotBeEmpty();var secondResolve=await Body(await Send(client,HttpMethod.Post,$"/api/sessions/{session}/narrative/resolve",adminToken,new{expectedStateVersion=firstResolve.GetProperty("stateVersion").GetInt64(),commandId=Guid.NewGuid()}));await WaitFor(displayConsequences,2);displayConsequences.Should().Contain(x=>x.EventType=="ConsequenceTriggered");var terminalVersion=secondResolve.GetProperty("stateVersion").GetInt64();terminalVersion.Should().BeGreaterThan(firstResolve.GetProperty("stateVersion").GetInt64());await WaitFor(supplierStateChanged,2);supplierStateChanged.Should().Contain(x=>x.EventType=="ChoiceRecorded"&&x.StateVersion==choice2.GetProperty("stateVersion").GetInt64());
        var rejectable=await Body(await Send(client,HttpMethod.Post,"/api/proposals",supplierToken,new{interactionTypeId="emergency-capacity-support",receiverTeamId=carrier,termsPayload=new{capacityUnits=5,supportDurationCheckpoints=1,publicDisclosure=false},validityType=(string?)null,validForCheckpointCount=(int?)null,validUntilCheckpointId=(string?)null,expectedStateVersion=terminalVersion,commandId=Guid.NewGuid()}));var rejectId=rejectable.GetProperty("resourceId").GetGuid();var rejected=await Body(await Send(client,HttpMethod.Post,$"/api/proposals/{rejectId}/reject",carrierToken,new{expectedRevisionNumber=1,expectedStateVersion=rejectable.GetProperty("stateVersion").GetInt64(),commandId=Guid.NewGuid()}));await WaitFor(supplierRejected,1);await WaitFor(carrierRejected,1);var cancellable=await Body(await Send(client,HttpMethod.Post,"/api/proposals",supplierToken,new{interactionTypeId="emergency-capacity-support",receiverTeamId=carrier,termsPayload=new{capacityUnits=5,supportDurationCheckpoints=1,publicDisclosure=false},validityType=(string?)null,validForCheckpointCount=(int?)null,validUntilCheckpointId=(string?)null,expectedStateVersion=rejected.GetProperty("stateVersion").GetInt64(),commandId=Guid.NewGuid()}));var cancelId=cancellable.GetProperty("resourceId").GetGuid();await Body(await Send(client,HttpMethod.Post,$"/api/proposals/{cancelId}/cancel",supplierToken,new{expectedRevisionNumber=1,expectedStateVersion=cancellable.GetProperty("stateVersion").GetInt64(),commandId=Guid.NewGuid()}));await WaitFor(supplierCancelled,1);await WaitFor(carrierCancelled,1);
    }

    private static async Task<string> Pair(HttpClient client,Guid session,Guid team,string code)=>(await Body(await client.PostAsJsonAsync($"/api/sessions/{session}/pair",new{teamId=team,pairingCode=code}))).GetProperty("accessToken").GetString()!;
    private static Task<HttpResponseMessage> Get(HttpClient client,string uri,string token){var request=new HttpRequestMessage(HttpMethod.Get,uri);request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);return client.SendAsync(request);}
    private static Task<HttpResponseMessage> Send(HttpClient client,HttpMethod method,string uri,string token,object body){var request=new HttpRequestMessage(method,uri){Content=JsonContent.Create(body)};request.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);return client.SendAsync(request);}
    private static HubConnection Hub(HambaftApiFactory factory,string token)=>new HubConnectionBuilder().WithUrl(new Uri(factory.Server.BaseAddress,"/hubs/session"),options=>{options.AccessTokenProvider=()=>Task.FromResult<string?>(token);options.Transports=HttpTransportType.LongPolling;options.HttpMessageHandlerFactory=_=>factory.Server.CreateHandler();}).Build();
    private static async Task WaitFor<T>(ConcurrentQueue<T> queue,int count){for(var i=0;i<40&&queue.Count<count;i++)await Task.Delay(50);queue.Count.Should().BeGreaterThanOrEqualTo(count);}
    private static async Task<JsonElement> Body(HttpResponseMessage response){response.EnsureSuccessStatusCode();using var document=JsonDocument.Parse(await response.Content.ReadAsStringAsync());return document.RootElement.Clone();}
}
